    "A3-S16-B04": {
      "id": "A3-S16-B04",
      "sceneId": "A3-S16",
      "type": "sequence",
      "messages": [
        {
          "id": "A3-S16-B04-M01",
          "sender": "nico",
          "text": "Gli ho detto che Anna è morta perché lui l'ha portata fin lì.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M02",
          "sender": "nico",
          "text": "Non ho usato \"attraversare\".",
          "delayMs": 3000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M03",
          "sender": "nico",
          "text": "Ho usato \"morta\".",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M04",
          "sender": "nico",
          "text": "Lui:",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M05",
          "sender": "nico",
          "text": "\"Anna ha scelto.\"",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M06",
          "sender": "nico",
          "text": "Io:",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M07",
          "sender": "nico",
          "text": "\"Le avete insegnato che ogni dubbio era paura.\"",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B04-M08",
          "sender": "nico",
          "text": "\"Le avete tolto tutte le uscite e poi avete chiamato scelta quella rimasta.\"",
          "delayMs": 3000,
          "delivery": "live"
        }
      ],
      "next": "A3-S16-B05"
    },
    "A3-S16-B05": {
      "id": "A3-S16-B05",
      "sceneId": "A3-S16",
      "type": "sequence",
      "messages": [
        {
          "id": "A3-S16-B05-M01",
          "sender": "nico",
          "text": "\"Tu credi che una scelta esista solo se nessuno ci ha influenzati?\"",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M02",
          "sender": "nico",
          "text": "Poi ha fatto l'elenco.",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M03",
          "sender": "nico",
          "text": "Famiglia.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M04",
          "sender": "nico",
          "text": "Amici.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M05",
          "sender": "nico",
          "text": "Paura.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M06",
          "sender": "nico",
          "text": "Lavoro.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M07",
          "sender": "nico",
          "text": "Società.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M08",
          "sender": "nico",
          "text": "Religione.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M09",
          "sender": "nico",
          "text": "Pubblicità.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B05-M10",
          "sender": "nico",
          "text": "Come se il fatto che tutti influenzino tutti rendesse innocente quello che ha fatto lui.",
          "delayMs": 3000,
          "delivery": "live"
        }
      ],
      "next": "A3-S16-B06"
    },
    "A3-S16-B06": {
      "id": "A3-S16-B06",
      "sceneId": "A3-S16",
      "type": "sequence",
      "messages": [
        {
          "id": "A3-S16-B06-M01",
          "sender": "nico",
          "text": "Gli ho detto che c'è una differenza tra influenzare qualcuno e costruire un mondo in cui smettere significa fallire.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M02",
          "sender": "nico",
          "text": "Elia non ha alzato la voce.",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M03",
          "sender": "nico",
          "text": "\"Anna poteva fermarsi.\"",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M04",
          "sender": "nico",
          "text": "\"Gli altri l'hanno fatto.\"",
          "delayMs": 3000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M05",
          "sender": "nico",
          "text": "Questa è la parte peggiore.",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M06",
          "sender": "nico",
          "text": "È vero.",
          "delayMs": 3000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B06-M07",
          "sender": "nico",
          "text": "E non lo assolve.",
          "delayMs": 3000,
          "delivery": "live"
        }
      ],
      "next": "A3-S16-B07"
    },
    "A3-S16-B07": {
      "id": "A3-S16-B07",
      "sceneId": "A3-S16",
      "type": "sequence",
      "messages": [
        {
          "id": "A3-S16-B07-M01",
          "sender": "nico",
          "text": "Ho capito una cosa.",
          "delayMs": 4000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M02",
          "sender": "nico",
          "text": "Non sta mentendo.",
          "delayMs": 2000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M03",
          "sender": "nico",
          "text": "Cioè.",
          "delayMs": 3000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M04",
          "sender": "nico",
          "text": "Può mentire su cento cose.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M05",
          "sender": "nico",
          "text": "Ma non su questa.",
          "delayMs": 2000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M06",
          "sender": "nico",
          "text": "Crede davvero che Anna abbia scelto.",
          "delayMs": 3000,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M07",
          "sender": "nico",
          "text": "Crede davvero che loro stiano scegliendo.",
          "delayMs": 0,
          "delivery": "live"
        },
        {
          "id": "A3-S16-B07-M08",
          "sender": "nico",
          "text": "Crede davvero al Giorno Bianco.",
          "delayMs": 4000,
          "delivery": "live"
        }
      ],
      "next": "A3-S16-ENDSTATE",
      "effects": [
        {
          "op": "set",
          "key": "KNOWS_ELIA_IS_SINCERE",
          "value": true
        }
      ]
    },
